my %h;
my $x = $h{a}{b};
say scalar(keys %h), defined $x ? 'def' : 'undef';
```

What does this program print?

```perl
use strict;
use warnings;
use feature qw(say);
my %reply = (
    hi  => sub { "hello, $_[0]" },
    bye => sub { "goodbye, $_[0]" },
);
for my $cmd (qw(hi bye yo)) {
    print exists $reply{$cmd} ? $reply{$cmd}->('Ana') : '?', ';';
}
print "\n";
```

